new Phaser.Game(config);

function preload() {
    this.startHeroFailed = false;
    this.load.on('loaderror', file => {
        if (file.key === 'start-screen-hero') this.startHeroFailed = true;
    });
    this.load.image('start-screen-hero', START_HERO_DATA_URL_V3);
}

function create() {
    this.gameOver = false;
    this.gameStarted = false;
    this.isPaused = false;
    this.score = 0;
    this.bonusCount = 0;
    this.lives = 3;
    this.invulnerable = false;
    this.power = 0;
    this.maxPower = 6;
    this.trickThresholds = [3, 6];
    this.lastTrickLevel = 0;
    this.trickInProgress = false;
    this.levelTwoTrickActive = false;
    this.bossTriggered = false;
    this.bossActive = false;
    this.bossDefeated = false;
    this.waterTruckTriggered = false;
    this.waterTruckDefeated = false;
    this.policeBossTriggered = false;
    this.policeBossDefeated = false;
    this.rivalBossTriggered = false;
    this.rivalBossDefeated = false;
    this.rivalWaitingForTrick = false;
    this.rivalChallengeTimer = 0;
    this.rivalCurrentTrick = 0;
    this.rivalLastTrick = 0;
    this.freeRide = false;
    this.nextFreeRideEnvironmentDistance = 0;
    this.nextWaterShotHigh = false;
    this.bossKind = null;
    this.bossFinishing = false;
    this.bossIntroPaused = false;
    this.bossIntroUnlockAt = 0;
    this.bossIntroText = '';
    this.bossThrowTimer = 0;
    this.nextBossThrow = 900;
    this.bossProjectiles = [];
    this.environmentPhase = 0;
    this.rampContactUntil = 0;
    this.rampJumpActive = false;
    this.rampJumpStartedAt = 0;
    this.speedBeforeRampJump = INITIAL_SPEED;
    this.lastSpawnWasRough = false;
    this.lastSpawnWasPlatform = false;
    this.skipNextRoughCourse = false;
    this.lastSpawnWasBird = false;
    this.speed = INITIAL_SPEED;
    this.spawnTimer = 0;
    this.nextSpawn = 1250;
    this.bonusSpawnTimer = 0;
    this.nextBonusSpawn = 2200;
    this.powerSpawnTimer = 0;
    this.nextPowerSpawn = 3600;
    this.distance = 0;

    createTextures(this);
    createWorld(this);
    createPlayer(this);
    createUI(this);
    createVerticalInfoArea(this);
    createVerticalTapArea(this);
    setGameOrientation(this, true);

    this.obstacles = this.physics.add.group({
        allowGravity: false,
        immovable: true
    });
    this.ramps = this.physics.add.group({
        allowGravity: false,
        immovable: true
    });
    this.platforms = this.physics.add.group({
        allowGravity: false,
        immovable: true
    });
    this.bonuses = this.physics.add.group({
        allowGravity: false,
        immovable: true
    });
    this.powerBonuses = this.physics.add.group({
        allowGravity: false,
        immovable: true
    });

    this.physics.add.collider(this.player, this.ground);
    this.physics.add.overlap(this.player, this.obstacles, hitObstacle, null, this);
    this.physics.add.overlap(this.player, this.bonuses, collectBonus, null, this);
    this.physics.add.overlap(this.player, this.powerBonuses, collectPower, null, this);
    this.physics.add.overlap(this.player, this.ramps, touchRamp, null, this);
    this.physics.add.collider(this.player, this.platforms, ridePlatform, canLandOnPlatform, this);

    this.cursors = this.input.keyboard.createCursorKeys();
    this.space = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

    this.input.on('pointerdown', (pointer, currentlyOver) => {
        if (currentlyOver?.includes(this.pauseButton)) return;
        if (currentlyOver?.includes(this.startButton)) return;
        if (!this.gameStarted) {
            const tappedVerticalControlArea = this.verticalOrientation && pointer.y >= GAME_HEIGHT * 2;
            if (tappedVerticalControlArea) startGame(this);
            return;
        }
        if (this.bossIntroPaused) {
            resumeBossIntro(this);
            return;
        }
        if (this.isPaused) return;
        if (this.gameOver) {
            restartGame(this);
            return;
        }
        jump(this);
    });

    this.input.keyboard.on('keydown-SPACE', () => {
        if (!this.gameStarted) {
            startGame(this);
            return;
        }
        if (this.bossIntroPaused) return;
        if (this.gameOver) {
            restartGame(this);
            return;
        }
        jump(this);
    });

    this.input.keyboard.on('keydown-UP', () => {
        if (!this.gameStarted) startGame(this);
        else if (this.bossIntroPaused) return;
        else if (this.gameOver) restartGame(this);
        else jump(this);
    });

    createStartScreen(this);

}

function restartGame(scene) {
    scene.physics.world.resume();
    scene.scene.restart();
}

function update(time, delta) {
    updateVerticalInfo(this);
    if (!this.gameStarted || this.gameOver || this.isPaused || this.bossIntroPaused) return;

    const dt = delta / 1000;

    if (!this.bossActive) {
        const speedAboveFalloff = Math.max(0, this.speed - ACCELERATION_FALLOFF_START);
        const acceleration = BASE_ACCELERATION / (1 + speedAboveFalloff / ACCELERATION_FALLOFF);
        this.speed += acceleration * dt;
    }
    if (!this.bossActive) this.distance += this.speed * dt;
    this.score = Math.floor(this.distance / 15);

    if (this.freeRide && this.score >= this.nextFreeRideEnvironmentDistance) {
        advanceEnvironment(this);
        this.nextFreeRideEnvironmentDistance += 3000;
    }

    if (!this.bossTriggered && this.score >= BOSS_DISTANCE) {
        startBossFight(this);
    } else if (this.bossDefeated && !this.waterTruckTriggered && this.score >= WATER_TRUCK_DISTANCE) {
        startWaterTruckFight(this);
    } else if (this.waterTruckDefeated && !this.policeBossTriggered && this.score >= POLICE_BOSS_DISTANCE) {
        startPoliceBossFight(this);
    } else if (this.policeBossDefeated && !this.rivalBossTriggered && this.score >= RIVAL_BOSS_DISTANCE) {
        startRivalBossFight(this);
    }

    this.scoreText.setText(formatDistanceProgress(this));
    this.speedText.setText(`${Math.floor(this.speed * 0.11)} km/h`);

    scrollWorld(this, dt);
    updatePlayer(this, dt);

    if (!this.bossActive || this.bossKind === 'rival') {
        this.spawnTimer += delta;
        if (this.spawnTimer >= this.nextSpawn) {
            this.spawnTimer = 0;
            const spawnedCourse = spawnObstacle(this);
            const difficulty = Phaser.Math.Clamp((this.speed - INITIAL_SPEED) / 400, 0, 1);
            this.nextSpawn = spawnedCourse === 'platform'
                ? this.platformCourseDurationMs
                : spawnedCourse === 'rough'
                ? 2900
                : Phaser.Math.Between(
                    Math.floor(1450 - difficulty * 380),
                    Math.floor(2050 - difficulty * 500)
                );
        }
        if (this.bossKind === 'rival') updateRivalBoss(this, delta);
    } else if (!this.bossFinishing) {
        this.spawnTimer = 0;
        this.bossThrowTimer += delta;
        if (this.bossThrowTimer >= this.nextBossThrow) {
            this.bossThrowTimer = 0;
            if (this.bossKind === 'water-truck') sprayBossWater(this);
            else if (this.bossKind === 'police') throwPoliceHazard(this);
            else throwBossTrash(this);
            this.nextBossThrow = this.bossKind === 'police'
                ? Phaser.Math.Between(5000, 8000)
                : Phaser.Math.Between(1700, 2600);
        }
    } else {
        this.spawnTimer = 0;
        this.bossThrowTimer = 0;
    }

    this.bonusSpawnTimer += delta;
    if (this.bonusSpawnTimer >= this.nextBonusSpawn) {
        this.bonusSpawnTimer = 0;
        spawnBonus(this);
        this.nextBonusSpawn = Phaser.Math.Between(2400, 3900);
    }

    if ((this.bossActive && !this.bossFinishing) || this.freeRide) {
        this.powerSpawnTimer += delta;
        if (this.powerSpawnTimer >= this.nextPowerSpawn) {
            this.powerSpawnTimer = 0;
            spawnPowerBonus(this);
            this.nextPowerSpawn = Phaser.Math.Between(1800, 3000);
        }
    } else {
        this.powerSpawnTimer = 0;
    }

    this.obstacles.getChildren().forEach(obstacle => {
        if (obstacle.isWaterBall && !obstacle.waterLanded) {
            obstacle.flightTime += dt;
            const t = Phaser.Math.Clamp(obstacle.flightTime / obstacle.flightDuration, 0, 1);
            obstacle.x = Phaser.Math.Linear(obstacle.startX, obstacle.endX, t);
            obstacle.y = obstacle.trajectoryY;
            obstacle.angle += 240 * dt;
            if (t >= 1) {
                obstacle.waterLanded = true;
                obstacle.angle = 0;
            }
        } else {
            const movementMultiplier = obstacle.isBird ? 1.2 : 1;
            obstacle.x -= this.speed * movementMultiplier * dt;
        }
        if (obstacle.isBird) {
            obstacle.y = obstacle.baseY + Math.sin(time * 0.012 + obstacle.phase) * 6;
            obstacle.angle = Math.sin(time * 0.018 + obstacle.phase) * 4;
        }
        if (obstacle.x < -120) obstacle.destroy();
    });

    this.ramps.getChildren().forEach(ramp => {
        ramp.x -= this.speed * dt;
        if (ramp.x < -120) ramp.destroy();
    });

    this.platforms.getChildren().forEach(platform => {
        platform.x -= this.speed * dt;
        if (platform.x + platform.displayWidth / 2 < -120) platform.destroy();
    });

    this.bonuses.getChildren().forEach(bonus => {
        bonus.x -= this.speed * dt;
        bonus.baseY = bonus.baseY || bonus.y;
        bonus.y = bonus.baseY + Math.round(Math.sin(time * 0.008 + bonus.phase) * 5);
        if (bonus.x < -120) bonus.destroy();
    });

    this.powerBonuses.getChildren().forEach(bonus => {
        bonus.x -= this.speed * dt;
        bonus.baseY = bonus.baseY || bonus.y;
        bonus.y = bonus.baseY + Math.round(Math.sin(time * 0.01 + bonus.phase) * 5);
        if (bonus.x < -120) bonus.destroy();
    });

    updateBossProjectiles(this, dt);
}

