    g.fillStyle(0xf2b880, 1);
    g.fillRect(58, 17, 11, 8);
    g.generateTexture('front-arm-up', 70, 108);

    // Build two complete rider sprites. Keeping the arms inside the same texture
    // prevents independent layers from drifting while the player is airborne.
    const buildRiderPose = (key, rearArmKey, frontArmKey) => {
        if (scene.textures.exists(key)) scene.textures.remove(key);
        const texture = scene.textures.createCanvas(key, 70, 108);
        const context = texture.context;
        context.imageSmoothingEnabled = false;
        context.clearRect(0, 0, 70, 108);
        context.drawImage(scene.textures.get(rearArmKey).getSourceImage(), 0, 0);
        context.drawImage(scene.textures.get('rider').getSourceImage(), 0, 0);
        context.drawImage(scene.textures.get(frontArmKey).getSourceImage(), 0, 0);
        texture.refresh();
    };
    buildRiderPose('rider-arms-down', 'rear-arm-down', 'front-arm-down');
    buildRiderPose('rider-arms-up', 'rear-arm-up', 'front-arm-up');

