    g.lineStyle(4, 0x70402c, 1);
    g.strokeRect(2, 2, 60, 50);
    g.beginPath();
    g.moveTo(5, 5);
    g.lineTo(59, 49);
    g.moveTo(59, 5);
    g.lineTo(5, 49);
    g.strokePath();
    g.generateTexture('box', 64, 54);

