function createWorld(scene) {
    scene.skyGraphics = scene.add.graphics();
    scene.worldGraphics = scene.add.graphics();
    scene.foregroundGraphics = scene.add.graphics().setDepth(14);

    drawStaticSky(scene);
    drawRoad(scene);

    scene.decor = [];

    // distant city silhouettes, all made with rectangles
    for (let i = 0; i < 17; i++) {
        const width = Phaser.Math.Between(45, 90);
        const height = Phaser.Math.Between(70, 180);
        const x = i * 95 + Phaser.Math.Between(-25, 25);
        scene.decor.push({
            type: 'building',
            x,
            width,
            height,
            parallax: 0.12
        });
    }

    // trees / poles nearer to road
    for (let i = 0; i < 12; i++) {
        scene.decor.push({
            type: i % 2 === 0 ? 'tree' : 'pole',
            x: 100 + i * 150,
            parallax: 0.4
        });
    }

    scene.roadMarks = [];
    scene.roadMarkSpacing = 150;
    scene.roadMarkCount = Math.ceil(GAME_WIDTH / scene.roadMarkSpacing) + 1;
    for (let i = 0; i < scene.roadMarkCount; i++) {
        scene.roadMarks.push({ x: i * 150 });
    }

    scene.foregroundDecor = [];
    for (let i = 0; i < 9; i++) {
        scene.foregroundDecor.push({
            type: 'tree',
            x: 80 + i * 190,
            parallax: Phaser.Math.FloatBetween(1.25, 1.45),
            scale: Phaser.Math.FloatBetween(0.85, 1.15)
        });
    }

    scene.ground = scene.add.rectangle(
        GAME_WIDTH / 2,
        ROAD_Y + (GAME_HEIGHT - ROAD_Y) / 2,
        GAME_WIDTH,
        GAME_HEIGHT - ROAD_Y,
        0x000000,
        0
    );
    scene.physics.add.existing(scene.ground, true);

    renderMovingWorld(scene);
}

function drawStaticSky(scene) {
    const g = scene.skyGraphics;
    const palette = ENVIRONMENTS[scene.environmentPhase];
    g.clear();

    g.fillStyle(palette.sky, 1);
    g.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    if (palette.key === 'night') {
        // A seeded generator gives independent-looking coordinates without
        // making the stars jump whenever the static sky is redrawn.
        let starSeed = 0x5f3759df;
        const randomStarValue = () => {
            starSeed = (Math.imul(1664525, starSeed) + 1013904223) >>> 0;
            return starSeed / 0x100000000;
        };
        for (let i = 0; i < 42; i++) {
            const starX = 30 + Math.floor(randomStarValue() * (GAME_WIDTH - 60));
            const starY = 28 + Math.floor(randomStarValue() * (ROAD_Y - 190));
            const bright = randomStarValue() > 0.78;
            g.fillStyle(bright ? 0xffffff : 0xb9d9e8, 1);
            g.fillRect(starX, starY, bright ? 5 : 3, bright ? 5 : 3);
            if (bright) {
                g.fillRect(starX - 4, starY + 2, 13, 2);
                g.fillRect(starX + 2, starY - 4, 2, 13);
            }
        }
    }

    let celestialX = GAME_WIDTH * 0.78;
    let celestialY = 110;
    if (palette.key === 'evening') {
        celestialX = GAME_WIDTH * 0.82;
        celestialY = ROAD_Y - 230;
    } else if (palette.key === 'morning') {
        celestialX = GAME_WIDTH * 0.10;
        celestialY = ROAD_Y - 150;
    }

    g.fillStyle(palette.celestial, 1);
    g.fillRect(celestialX, celestialY, 72, 72);
    g.fillStyle(palette.celestialInner, 1);
    g.fillRect(celestialX + 12, celestialY + 12, 48, 48);

    if (palette.key === 'night') {
        // Cut a stepped bite out of the light square to form a pixel crescent moon.
        g.fillStyle(palette.sky, 1);
        g.fillRect(celestialX + 38, celestialY + 4, 34, 48);
        g.fillRect(celestialX + 30, celestialY + 12, 34, 32);
    }

    // clouds
    g.fillStyle(palette.cloud, 1);
    drawCloud(g, GAME_WIDTH * 0.12, 110, 1.0);
    drawCloud(g, GAME_WIDTH * 0.50, 175, 0.75);
    drawCloud(g, GAME_WIDTH * 0.86, 245, 0.6);
}

function drawCloud(g, x, y, s) {
    const u = Math.max(4, Math.round(8 * s));
    g.fillRect(x, y, u * 10, u * 3);
    g.fillRect(x + u * 2, y - u * 2, u * 5, u * 2);
    g.fillRect(x + u * 3, y - u * 3, u * 3, u);
}

function drawRoad(scene) {
    // actual road is rendered each frame in renderMovingWorld
}

function renderMovingWorld(scene) {
    const g = scene.worldGraphics;
    const palette = ENVIRONMENTS[scene.environmentPhase];
    g.clear();

    // background buildings
    scene.decor
        .filter(o => o.type === 'building')
        .forEach(o => {
            const baseY = ROAD_Y - 60;
            g.fillStyle(palette.building, 1);
            g.fillRect(o.x, baseY - o.height, o.width, o.height);

            if (palette.key === 'night') {
                g.fillStyle(palette.window, 1);
                for (let wy = baseY - o.height + 16; wy < baseY - 12; wy += 24) {
                    for (let wx = o.x + 12; wx < o.x + o.width - 8; wx += 22) {
                        g.fillRect(wx, wy, 8, 8);
                    }
                }
            }
        });

    // sidewalk
    g.fillStyle(palette.sidewalk, 1);
    g.fillRect(0, ROAD_Y - 60, GAME_WIDTH, 60);

    // near decorations
    scene.decor
        .filter(o => o.type !== 'building')
        .forEach(o => {
            if (o.type === 'tree') {
                g.fillStyle(palette.trunk, 1);
                g.fillRect(o.x - 8, ROAD_Y - 114, 16, 70);
                g.fillStyle(palette.leafDark, 1);
                g.fillRect(o.x - 32, ROAD_Y - 160, 64, 48);
                g.fillStyle(palette.leafLight, 1);
                g.fillRect(o.x - 20, ROAD_Y - 172, 40, 20);
                g.fillRect(o.x - 42, ROAD_Y - 140, 28, 22);
                g.fillRect(o.x + 18, ROAD_Y - 144, 26, 26);
            } else {
                g.fillStyle(palette.pole, 1);
                g.fillRect(o.x - 4, ROAD_Y - 136, 8, 90);
                g.fillStyle(palette.poleDark, 1);
                g.fillRect(o.x - 20, ROAD_Y - 140, 40, 14);
                g.fillStyle(palette.roadMark, 1);
                g.fillRect(o.x - 12, ROAD_Y - 136, 24, 6);
            }
        });

    // curb
    g.fillStyle(palette.curb, 1);
    g.fillRect(0, ROAD_Y - 13, GAME_WIDTH, 13);

    // road
    g.fillStyle(palette.road, 1);
    g.fillRect(0, ROAD_Y, GAME_WIDTH, GAME_HEIGHT - ROAD_Y);

    // lane marks
    g.fillStyle(palette.roadMark, 1);
    scene.roadMarks.forEach(mark => {
        g.fillRect(Math.round(mark.x), ROAD_Y + 64, 72, 8);
    });

    // subtle top road line
    g.fillStyle(palette.roadEdge, 1);
    g.fillRect(0, ROAD_Y, GAME_WIDTH, 6);

    renderForeground(scene);
}

function renderForeground(scene) {
    const g = scene.foregroundGraphics;
    const palette = ENVIRONMENTS[scene.environmentPhase];
    g.clear();

    scene.foregroundDecor.forEach(object => {
        const x = Math.round(object.x);
        const s = object.scale;

        if (object.type === 'tree') {
            const trunkWidth = Math.round(22 * s);
            const crownWidth = Math.round(94 * s);
            const crownHeight = Math.round(58 * s);
            const crownY = GAME_HEIGHT - Math.round(62 * s);

            g.fillStyle(palette.trunk, 1);
            g.fillRect(x - trunkWidth / 2, crownY + 24, trunkWidth, GAME_HEIGHT - crownY + 30);
            g.fillStyle(palette.leafDark, 1);
            g.fillRect(x - crownWidth / 2, crownY, crownWidth, crownHeight);
            g.fillStyle(palette.leafLight, 1);
            g.fillRect(x - crownWidth * 0.32, crownY - 16, crownWidth * 0.64, 24);
            g.fillRect(x - crownWidth * 0.62, crownY + 18, crownWidth * 0.28, 28);
            g.fillRect(x + crownWidth * 0.34, crownY + 14, crownWidth * 0.28, 30);
        }
    });
}

function scrollWorld(scene, dt) {
    scene.decor.forEach(o => {
        o.x -= scene.speed * o.parallax * dt;

        if (o.x < -120) {
            if (o.type === 'building') {
                o.x = GAME_WIDTH + Phaser.Math.Between(80, 220);
                o.height = Phaser.Math.Between(70, 180);
                o.width = Phaser.Math.Between(45, 90);
            } else {
                const lastNearObjectX = Math.max(
                    GAME_WIDTH,
                    ...scene.decor
                        .filter(other => other !== o && other.type !== 'building')
                        .map(other => other.x)
                );
                o.x = lastNearObjectX + 150;
            }
        }
    });

    scene.roadMarks.forEach(mark => {
        mark.x -= scene.speed * dt;
        if (mark.x < -100) mark.x += scene.roadMarkCount * scene.roadMarkSpacing;
    });

    scene.foregroundDecor.forEach(object => {
        object.x -= scene.speed * object.parallax * dt;
        if (object.x < -120) {
            object.x = GAME_WIDTH + Phaser.Math.Between(120, 300);
            object.scale = Phaser.Math.FloatBetween(0.85, 1.15);
        }
    });

    renderMovingWorld(scene);
}

function createPlayer(scene) {
    scene.board = scene.add.image(PLAYER_X, ROAD_Y - 8, 'board');
    scene.board.setDepth(5);

    scene.player = scene.physics.add.sprite(PLAYER_X, ROAD_Y - 63, 'rider-arms-down');
    scene.player.setDepth(6);
    scene.player.setOrigin(0.5, 1);
    scene.player.body.setSize(38, 90);
    scene.player.body.setOffset(16, 12);
    scene.player.setCollideWorldBounds(true);

    // invisible feet sensor approximation via body touching.down
    scene.playerStartY = scene.player.y;
    scene.playerAngle = 0;
    scene.jumpArmsRaised = false;
}

