function createFallbackStartHero(scene) {
    const fallback = scene.add.container(0, 0);
    const art = scene.add.graphics();
    art.fillStyle(0x65c6d4, 1);
    art.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
    art.fillStyle(0x50648a, 1);
    for (let x = 0; x < GAME_WIDTH; x += 150) {
        const height = 130 + ((x * 7) % 170);
        art.fillRect(x, ROAD_Y - height, 105, height);
    }
    art.fillStyle(0x33415c, 1);
    art.fillRect(0, ROAD_Y, GAME_WIDTH, GAME_HEIGHT - ROAD_Y);
    art.fillStyle(0xffd166, 1);
    for (let x = 0; x < GAME_WIDTH; x += 180) art.fillRect(x, ROAD_Y + 95, 92, 10);
    art.lineStyle(8, 0xe8f3dc, 0.55);
    for (let i = 0; i < 9; i++) {
        art.beginPath();
        art.moveTo(GAME_WIDTH / 2, GAME_HEIGHT / 2);
        art.lineTo(i * 190 - 80, GAME_HEIGHT);
        art.strokePath();
    }

    const rider = scene.add.image(GAME_WIDTH / 2, GAME_HEIGHT / 2 - 35, 'rider')
        .setScale(4.4)
        .setAngle(-8);
    const board = scene.add.image(GAME_WIDTH / 2 + 55, GAME_HEIGHT / 2 + 165, 'board')
        .setScale(4.8)
        .setAngle(-12);
    fallback.add([art, rider, board]);
    return fallback;
}

function startGame(scene) {
    if (scene.gameStarted) return;
    scene.gameStarted = true;
    scene.physics.world.resume();
    scene.pauseButton.setVisible(true);
    scene.pauseButtonIcon.setVisible(true);
    if (scene.startScreen?.active) scene.startScreen.destroy(true);
    scene.startScreen = null;
}

function createPauseButton(scene) {
    const buttonSize = 64;
    const x = GAME_WIDTH - 18 - buttonSize / 2;
    const y = GAME_HEIGHT - 18 - buttonSize / 2;

    scene.pauseButton = scene.add.rectangle(x, y, buttonSize, buttonSize, 0x182744, 0.82)
        .setStrokeStyle(4, 0xffd166, 1)
        .setDepth(50)
        .setScrollFactor(0)
        .setInteractive({ useHandCursor: true });
    scene.pauseButtonIcon = scene.add.text(x, y, 'Ⅱ', {
        fontFamily: 'monospace',
        fontSize: '32px',
        fontStyle: 'bold',
        color: '#ffffff'
    }).setOrigin(0.5).setDepth(51).setScrollFactor(0);

    scene.pauseButton.on('pointerdown', () => togglePause(scene));
}

function togglePause(scene) {
    scene.isPaused = !scene.isPaused;
    if (scene.isPaused) {
        scene.physics.world.pause();
        scene.tweens.pauseAll();
        scene.time.paused = true;
        scene.pauseButtonIcon.setText('▶').setColor('#ffd166');
    } else {
        scene.physics.world.resume();
        scene.tweens.resumeAll();
        scene.time.paused = false;
        scene.pauseButtonIcon.setText('Ⅱ').setColor('#ffffff');
    }
}

function showBossIntro(scene, title, instructions) {
    if (!scene.verticalOrientation || !scene.verticalInfo) return;
    scene.bossIntroPaused = true;
    scene.bossIntroText = `${title}\n${instructions}`;
    scene.bossIntroUnlockAt = performance.now() + 1500;
    scene.verticalInfo.bossHint.setText(`${title}\n${instructions}`);
    scene.verticalInfo.bossHelp.setText(BOSS_TRICK_HELP);
    scene.verticalInfo.bossPrompt.setText('GET READY...');
    scene.physics.world.pause();
    scene.tweens.pauseAll();
    scene.time.paused = true;
    scene.pauseButton.setVisible(false);
    scene.pauseButtonIcon.setVisible(false);
}

function resumeBossIntro(scene) {
    if (!scene.bossIntroPaused) return;
    if (performance.now() < scene.bossIntroUnlockAt) return;
    scene.bossIntroPaused = false;
    scene.bossIntroText = '';
    scene.verticalInfo.bossHint.setText('');
    scene.verticalInfo.bossHelp.setText('');
    scene.verticalInfo.bossPrompt.setText('');
    scene.physics.world.resume();
    scene.tweens.resumeAll();
    scene.time.paused = false;
    scene.pauseButton.setVisible(true);
    scene.pauseButtonIcon.setVisible(true);
}

function redrawHudPanel(scene, showPower) {
    const height = showPower ? 206 : 140;
    scene.uiPanel.clear();
    scene.uiPanel.fillStyle(0x182744, 1);
    scene.uiPanel.fillRect(20, 20, 390, height);
    scene.uiPanel.lineStyle(4, 0xffd166, 1);
    scene.uiPanel.strokeRect(20, 20, 390, height);
}

function formatDistanceProgress(scene) {
    let nextBossDistance = null;
    if (!scene.bossDefeated) nextBossDistance = BOSS_DISTANCE;
    else if (!scene.waterTruckDefeated) nextBossDistance = WATER_TRUCK_DISTANCE;
    else if (!scene.policeBossDefeated) nextBossDistance = POLICE_BOSS_DISTANCE;
    else if (!scene.rivalBossDefeated) nextBossDistance = RIVAL_BOSS_DISTANCE;

    const current = String(scene.score).padStart(5, '0');
    if (nextBossDistance === null) return `DIST ${current} / FREE RIDE`;
    return `DIST ${current} / ${String(nextBossDistance).padStart(5, '0')} m`;
}

function setPowerHudVisible(scene, visible) {
    scene.powerHudEnabled = visible;
    redrawHudPanel(scene, visible);
    const showHorizontalPower = visible && !scene.verticalOrientation;
    scene.powerLabel.setVisible(showHorizontalPower);
    scene.powerGraphics.setVisible(showHorizontalPower);
    scene.powerText.setVisible(showHorizontalPower);
    scene.trickText.setVisible(showHorizontalPower);
    updateVerticalInfo(scene);
}

function redrawLives(scene) {
    scene.livesIcons.removeAll(true);
    for (let index = 0; index < scene.lives; index++) {
        const lifeBoard = scene.add.image(index * 35, 0, 'board')
            .setOrigin(0, 0.5)
            .setDisplaySize(32, 14);
        scene.livesIcons.add(lifeBoard);
    }
    redrawVerticalLives(scene);
}

function jump(scene) {
    if (scene.isPaused) return;
    if (scene.player.body.blocked.down || scene.player.body.touching.down) {
        const rampBoosted = scene.time.now <= scene.rampContactUntil;
        if (rampBoosted) {
            scene.speedBeforeRampJump = scene.speed;
            scene.speed *= RAMP_SPEED_MULTIPLIER;
            scene.rampJumpActive = true;
            scene.rampJumpStartedAt = scene.time.now;
        }
        // Use the final jump pose immediately, with no transitional arm movement.
        scene.player.setTexture('rider-arms-up');
        scene.jumpArmsRaised = true;
        const jumpVelocity = rampBoosted ? RAMP_JUMP_VELOCITY : NORMAL_JUMP_VELOCITY;
        scene.jumpLaunchSpeed = Math.abs(jumpVelocity);
        scene.player.setAngle(-6);
        scene.player.setVelocityY(jumpVelocity);
        if (rampBoosted) scene.rampContactUntil = 0;
    } else {
        tryPerformTrick(scene);
    }
}

function updatePlayer(scene, dt) {
    const grounded = scene.player.body.blocked.down || scene.player.body.touching.down;
    // Latch the jump pose for the whole flight. Phaser contact flags can briefly
    // flicker in mid-air, so they must not directly control the arm textures.
    if (scene.player.body.velocity.y < -1) scene.jumpArmsRaised = true;
    if (scene.jumpArmsRaised && grounded && scene.player.body.velocity.y >= 0) {
        scene.jumpArmsRaised = false;
    }
    const armsUp = scene.jumpArmsRaised;

    if (grounded) {
        if (scene.rampJumpActive && scene.time.now - scene.rampJumpStartedAt > 100) {
            restoreRampSpeed(scene);
        }
        if (scene.levelTwoTrickActive) {
            resetRiderStance(scene);
        }
        // simple riding bob
        scene.player.y += Math.sin(scene.time.now * 0.012) * 0.18;
        const ridingPlatform = scene.player.body.bottom < ROAD_Y - 24;
        scene.board.y = ridingPlatform ? scene.player.y - 14 : ROAD_Y - 8;
        scene.player.setAngle(0);
        scene.board.angle = 0;
    } else {
        // Tilt left at takeoff, then smoothly level out at the jump apex.
        if (scene.player.body.velocity.y < 0) {
            const launchSpeed = scene.jumpLaunchSpeed || Math.abs(NORMAL_JUMP_VELOCITY);
            const ascentRatio = Phaser.Math.Clamp(-scene.player.body.velocity.y / launchSpeed, 0, 1);
            scene.player.setAngle(-6 * ascentRatio);
        } else {
            scene.player.setAngle(0);
        }
        // player origin is at the feet: keep the deck locked directly below them
        scene.board.y = scene.player.y - 8;
        scene.board.angle = scene.player.angle;
    }

    const riderTexture = armsUp ? 'rider-arms-up' : 'rider-arms-down';
    if (scene.player.texture.key !== riderTexture) scene.player.setTexture(riderTexture);
    if (scene.playerTrickNameText?.active) {
        scene.playerTrickNameText.setPosition(scene.player.x, scene.player.y - 132);
    }
}

function restoreRampSpeed(scene) {
    if (!scene.rampJumpActive) return;
    scene.speed = scene.speedBeforeRampJump;
    scene.rampJumpActive = false;
}

function startBossFight(scene) {
    scene.bossTriggered = true;
    scene.bossActive = true;
    scene.bossKind = 'scooter';
    scene.distance = BOSS_DISTANCE * 15;
    scene.score = BOSS_DISTANCE;
    scene.power = 0;
    scene.maxPower = 6;
    scene.trickThresholds = [3, 6];
    scene.powerSpawnTimer = 0;
    scene.nextPowerSpawn = 500;
    scene.obstacles.clear(true, true);
    scene.ramps.clear(true, true);
    scene.platforms.clear(true, true);
    scene.spawnTimer = 0;
    scene.bossThrowTimer = 0;
    scene.nextBossThrow = 900;
    setPowerHudVisible(scene, true);
    redrawPowerMeter(scene);

    scene.boss = scene.add.image(GAME_WIDTH * 0.68, BOSS_ROAD_Y, 'scooter-boss');
    scene.boss.setOrigin(0.5, 1).setDepth(9);
    scene.boss.coolness = 0;
    scene.boss.maxCoolness = BOSS_MAX_COOLNESS;

    scene.bossHud = scene.add.container(GAME_WIDTH / 2, 34).setDepth(40);
    scene.bossHudGraphics = scene.add.graphics();
    scene.bossHudLabel = scene.add.text(0, 0, 'SCOOTER COOLNESS', {
        fontFamily: 'monospace',
        fontSize: '20px',
        fontStyle: 'bold',
        color: '#ffffff'
    }).setOrigin(0.5, 0);
    scene.bossHud.add([scene.bossHudGraphics, scene.bossHudLabel]);
    redrawBossCoolness(scene);

    const warning = scene.add.text(GAME_WIDTH / 2, GAME_HEIGHT * 0.32, 'BOSS!', {
        fontFamily: 'monospace',
        fontSize: '54px',
        fontStyle: 'bold',
        color: '#f45b69',
        stroke: '#182744',
        strokeThickness: 8
    }).setOrigin(0.5).setDepth(39);
    scene.tweens.add({
        targets: warning,
        alpha: 0,
        y: warning.y - 30,
        duration: 900,
        onComplete: () => warning.destroy()
    });
    showBossIntro(
        scene,
        'BOSS 1: SCOOTER RIDER',
        'This scooter rider is behaving badly—throwing trash onto the road and not watching where he is going. Land a few tricks to show him how riding is done.'
    );
}

function startWaterTruckFight(scene) {
    scene.waterTruckTriggered = true;
    scene.bossActive = true;
    scene.bossKind = 'water-truck';
    scene.distance = WATER_TRUCK_DISTANCE * 15;
    scene.score = WATER_TRUCK_DISTANCE;
    scene.power = 0;
    scene.maxPower = 9;
    scene.trickThresholds = [3, 6, 9];
    scene.powerSpawnTimer = 0;
    scene.nextPowerSpawn = 500;
    scene.obstacles.clear(true, true);
    scene.ramps.clear(true, true);
    scene.platforms.clear(true, true);
    scene.spawnTimer = 0;
    scene.bossThrowTimer = 0;
    scene.nextBossThrow = 750;
    setPowerHudVisible(scene, true);
    redrawPowerMeter(scene);

    scene.boss = scene.add.image(GAME_WIDTH - 185, BOSS_ROAD_Y, 'water-truck-boss');
    scene.boss.setOrigin(0.5, 1).setDepth(9).setScale(1.35).setFlipX(true);
    scene.boss.coolness = 0;
    scene.boss.maxCoolness = 18;

    scene.bossHud = scene.add.container(GAME_WIDTH / 2, 34).setDepth(40);
    scene.bossHudGraphics = scene.add.graphics();
    scene.bossHudLabel = scene.add.text(0, 0, 'WATER TRUCK PRESSURE', {
        fontFamily: 'monospace',
        fontSize: '20px',
        fontStyle: 'bold',
        color: '#ffffff'
    }).setOrigin(0.5, 0);
    scene.bossHud.add([scene.bossHudGraphics, scene.bossHudLabel]);
    redrawBossCoolness(scene);

    const warning = scene.add.text(GAME_WIDTH / 2, GAME_HEIGHT * 0.32, 'BOSS 2: WATER TRUCK!', {
        fontFamily: 'monospace',
        fontSize: '46px',
        fontStyle: 'bold',
        color: '#65c6d4',
        stroke: '#182744',
        strokeThickness: 8
    }).setOrigin(0.5).setDepth(39);
    scene.tweens.add({
        targets: warning,
        alpha: 0,
        y: warning.y - 30,
        duration: 1200,
        onComplete: () => warning.destroy()
    });
    showBossIntro(
        scene,
        'BOSS 2: WATER TRUCK',
        "Water trucks and riders are natural enemies. Show it a few tricks and make the driver's pressure rise! Watch out for the water—it can come from below or above."
    );
}

