function touchRamp(player, ramp) {
    if (this.gameOver || !ramp.active) return;
    this.rampContactUntil = this.time.now + 130;
}

function spawnBonus(scene) {
    const heights = [ROAD_Y - 145, ROAD_Y - 205];
    const bonus = scene.bonuses.create(
        GAME_WIDTH + 80,
        Phaser.Utils.Array.GetRandom(heights),
        'bonus'
    );
    bonus.setDepth(8);
    bonus.body.setCircle(21, 3, 3);
    bonus.baseY = bonus.y;
    bonus.phase = Phaser.Math.FloatBetween(0, Math.PI * 2);
}

function collectBonus(player, bonus) {
    if (!bonus.active || this.gameOver) return;

    const x = bonus.x;
    const y = bonus.y;
    bonus.disableBody(true, true);
    addABonuses(this, 1);

    const pickupText = this.add.text(x, y, '+A', {
        fontFamily: 'monospace',
        fontSize: '24px',
        fontStyle: 'bold',
        color: '#ffd166',
        stroke: '#182744',
        strokeThickness: 4
    }).setOrigin(0.5).setDepth(30);

    this.tweens.add({
        targets: pickupText,
        y: y - 40,
        alpha: 0,
        duration: 450,
        onComplete: () => pickupText.destroy()
    });
}

function awardFreeRideTrickBonus(scene, level) {
    const rewards = [1, 3, 8, 12];
    const amount = rewards[level - 1] || level;
    addABonuses(scene, amount);

    const rewardText = scene.add.text(scene.player.x, scene.player.y - 125, `+${amount} A`, {
        fontFamily: 'monospace', fontSize: '26px', fontStyle: 'bold',
        color: '#ffd166', stroke: '#182744', strokeThickness: 4
    }).setOrigin(0.5).setDepth(35);
    scene.tweens.add({
        targets: rewardText,
        y: rewardText.y - 50,
        alpha: 0,
        duration: 700,
        onComplete: () => rewardText.destroy()
    });
    return amount;
}

function addABonuses(scene, amount) {
    const previousLifeMilestones = Math.floor(scene.bonusCount / LIFE_BONUS_INTERVAL);
    scene.bonusCount += amount;
    scene.bonusText.setText(`A x ${String(scene.bonusCount).padStart(2, '0')}`);

    const reachedLifeMilestones = Math.floor(scene.bonusCount / LIFE_BONUS_INTERVAL);
    const earnedLives = reachedLifeMilestones - previousLifeMilestones;
    if (earnedLives <= 0 || scene.lives >= 6) return;

    const addedLives = Math.min(earnedLives, 6 - scene.lives);
    scene.lives += addedLives;
    redrawLives(scene);

    const lifeText = scene.add.text(GAME_WIDTH / 2, 185, `+${addedLives} LIFE`, {
        fontFamily: 'monospace', fontSize: '50px', fontStyle: 'bold',
        color: '#f45b69', stroke: '#182744', strokeThickness: 8
    }).setOrigin(0.5).setDepth(40);
    scene.tweens.add({
        targets: lifeText,
        y: lifeText.y - 55,
        alpha: 0,
        delay: 2000,
        duration: 1000,
        onComplete: () => lifeText.destroy()
    });
}

function spawnPowerBonus(scene) {
    const heights = [ROAD_Y - 145, ROAD_Y - 205];
    const bonus = scene.powerBonuses.create(
        GAME_WIDTH + 80,
        Phaser.Utils.Array.GetRandom(heights),
        'power-placeholder'
    );
    bonus.setDepth(8);
    bonus.body.setCircle(21, 3, 3);
    bonus.baseY = bonus.y;
    bonus.phase = Phaser.Math.FloatBetween(0, Math.PI * 2);
}

function collectPower(player, bonus) {
    if (!bonus.active || this.gameOver) return;

    bonus.disableBody(true, true);
    this.power = Math.min(this.maxPower, this.power + 1);
    redrawPowerMeter(this);
}

function redrawPowerMeter(scene) {
    const x = 39;
    const y = 169;
    const width = 200;
    const height = 18;
    const ratio = Phaser.Math.Clamp(scene.power / scene.maxPower, 0, 1);
    const readyLevel = getAvailableTrickLevel(scene);
    const fillColor = readyLevel >= 4 ? 0xffffff : readyLevel >= 3 ? 0xf45b69 : readyLevel >= 2 ? 0xffd166 : readyLevel >= 1 ? 0x65c6d4 : 0x50648a;

    scene.powerGraphics.clear();
    scene.powerGraphics.fillStyle(0x101828, 1);
    scene.powerGraphics.fillRect(x, y, width, height);
    scene.powerGraphics.fillStyle(fillColor, 1);
    scene.powerGraphics.fillRect(x + 3, y + 3, Math.floor((width - 6) * ratio), height - 6);
    scene.powerGraphics.lineStyle(3, 0xe8f3dc, 1);
    scene.powerGraphics.strokeRect(x, y, width, height);

    // Threshold markers stay data-driven when maxPower grows in future updates.
    scene.trickThresholds.forEach(threshold => {
        if (threshold >= scene.maxPower) return;
        const markerX = x + Math.round(width * threshold / scene.maxPower);
        scene.powerGraphics.fillStyle(0xe8f3dc, 1);
        scene.powerGraphics.fillRect(markerX - 2, y - 3, 4, height + 6);
    });

    scene.powerText.setText(`${scene.power}/${scene.maxPower}`);
    if (readyLevel > 0) {
        const trickNames = ['POP SHOW-IT', '180', 'KICKFLIP', '360 FLIP'];
        scene.trickText.setText(`${trickNames[readyLevel - 1]} READY - JUMP`);
        scene.trickText.setColor(readyLevel >= 4 ? '#ffffff' : readyLevel >= 3 ? '#f45b69' : readyLevel >= 2 ? '#ffd166' : '#65c6d4');
    } else {
        scene.trickText.setText('TRICK: NOT READY');
        scene.trickText.setColor('#93b2bb');
    }
}

function getAvailableTrickLevel(scene) {
    let level = 0;
    scene.trickThresholds.forEach((threshold, index) => {
        if (scene.power >= threshold) level = index + 1;
    });
    return level;
}

function tryPerformTrick(scene) {
    if (scene.trickInProgress) return;

    const grounded = scene.player.body.blocked.down || scene.player.body.touching.down;
    if (grounded) {
        scene.trickText.setText('JUMP FIRST!');
        scene.trickText.setColor('#f45b69');
        scene.time.delayedCall(650, () => redrawPowerMeter(scene));
        return;
    }

    const level = getAvailableTrickLevel(scene);
    if (level === 0) {
        scene.trickText.setText('NOT ENOUGH POWER');
        scene.trickText.setColor('#f45b69');
        scene.time.delayedCall(650, () => redrawPowerMeter(scene));
        return;
    }

    const cost = scene.trickThresholds[level - 1];
    scene.power -= cost;
    scene.lastTrickLevel = level;
    playTrickAnimation(scene, level);
    showPlayerTrickName(scene, level);
    let freeRideReward = 0;
    if (scene.bossKind === 'rival') handleRivalTrick(scene, level);
    else if (scene.freeRide) freeRideReward = awardFreeRideTrickBonus(scene, level);
    else addBossCoolness(scene, level);
    redrawPowerMeter(scene);
    const bossTrickNames = [
        'POP SHOW-IT! +2 COOLNESS',
        '180! +4 COOLNESS',
        'KICKFLIP! +8 COOLNESS',
        '360 FLIP! +12 COOLNESS'
    ];
    scene.trickText.setText(
        scene.freeRide
            ? `${TRICK_NAMES[level - 1]}! +${freeRideReward} A`
            : bossTrickNames[level - 1]
    );
    scene.trickText.setColor(level >= 4 ? '#ffffff' : level >= 3 ? '#f45b69' : level >= 2 ? '#ffd166' : '#65c6d4');
    scene.time.delayedCall(700, () => redrawPowerMeter(scene));
}

function showPlayerTrickName(scene, level) {
    if (scene.playerTrickNameText?.active) scene.playerTrickNameText.destroy();

    const label = scene.add.text(
        scene.player.x,
        scene.player.y - 132,
        TRICK_NAMES[level - 1],
        {
            fontFamily: 'monospace', fontSize: '22px', fontStyle: 'bold',
            color: '#ffd166', stroke: '#182744', strokeThickness: 5,
            backgroundColor: '#182744cc', padding: { x: 8, y: 5 }
        }
    ).setOrigin(0.5).setDepth(35);

    scene.playerTrickNameText = label;
    scene.tweens.add({
        targets: label,
        alpha: 0,
        delay: 550,
        duration: 350,
        onComplete: () => {
            if (label.active) label.destroy();
            if (scene.playerTrickNameText === label) scene.playerTrickNameText = null;
        }
    });
}

function playBoardFlipFrames(scene, board, onComplete) {
    const originalScaleX = board.scaleX;
    const originalScaleY = Math.abs(board.scaleY) || 1;
    const frames = [
        { delay: 90, texture: 'board-top', flipY: false },
        { delay: 220, texture: 'board', flipY: true },
        { delay: 350, texture: 'board-bottom', flipY: false },
        { delay: 520, texture: 'board', flipY: false, complete: true }
    ];

    board.setTexture('board').setFlipY(false);
    board.setScale(originalScaleX, originalScaleY);
    frames.forEach(frame => {
        scene.time.delayedCall(frame.delay, () => {
            if (!board.active) return;
            board.setTexture(frame.texture).setFlipY(frame.flipY);
            if (frame.complete) {
                board.setScale(originalScaleX, originalScaleY);
                if (onComplete) onComplete();
            }
        });
    });
}

function playTrickAnimation(scene, level) {
    if (level === 1) {
        scene.trickInProgress = true;
        const targetScaleX = scene.board.scaleX > 0 ? -1 : 1;

        scene.tweens.add({
            targets: scene.board,
            scaleX: targetScaleX,
            duration: 360,
            ease: 'Sine.easeInOut',
            onComplete: () => {
                scene.board.setScale(targetScaleX, 1);
                scene.trickInProgress = false;
            }
        });
        scene.tweens.add({
            targets: scene.board,
            scaleY: 0.82,
            duration: 180,
            ease: 'Sine.easeInOut',
            yoyo: true
        });
        return;
    }

    if (level === 2) {
        scene.trickInProgress = true;
        scene.levelTwoTrickActive = true;
        scene.tweens.killTweensOf([scene.player, scene.board]);

        const targetScaleX = scene.player.scaleX > 0 ? -1 : 1;
        scene.tweens.add({
            targets: [scene.player, scene.board],
            scaleX: targetScaleX,
            duration: 440,
            ease: 'Sine.easeInOut',
            onComplete: () => {
                scene.player.setScale(targetScaleX, 1);
                scene.board.setScale(targetScaleX, 1);
                scene.trickInProgress = false;
            }
        });
        scene.tweens.add({
            targets: [scene.player, scene.board],
            scaleY: 0.9,
            duration: 220,
            ease: 'Sine.easeInOut',
            yoyo: true
        });
        return;
    }

    if (level === 3) {
        scene.trickInProgress = true;
        scene.tweens.killTweensOf(scene.board);
        playBoardFlipFrames(scene, scene.board, () => {
            scene.trickInProgress = false;
        });
        return;
    }

    if (level === 4) {
        scene.trickInProgress = true;
        scene.tweens.killTweensOf(scene.board);
        const originalScaleX = scene.board.scaleX;

        // Vertical-axis rotation runs alongside the top/underside flip frames.
        scene.tweens.add({
            targets: scene.board,
            scaleX: -originalScaleX,
            duration: 260,
            ease: 'Sine.easeInOut',
            yoyo: true
        });
        playBoardFlipFrames(scene, scene.board, () => {
            scene.board.setScale(originalScaleX, 1);
            scene.trickInProgress = false;
        });
    }
}

function resetRiderStance(scene) {
    scene.tweens.killTweensOf([scene.player, scene.board]);
    scene.player.setScale(1, 1);
    scene.board.setScale(1, 1);
    scene.player.setAngle(0);
    scene.board.setAngle(0);
    scene.levelTwoTrickActive = false;
    scene.trickInProgress = false;
}

function hitObstacle(player, obstacle) {
    if (this.gameOver || this.invulnerable) return;

    if (this.levelTwoTrickActive) resetRiderStance(this);

    obstacle.destroy();
    // A collision during the ramp landing used to clear the flag before the
    // temporary 1.45x boost could be removed. Restore the pre-ramp speed only.
    restoreRampSpeed(this);
    if (!TEST_INFINITE_LIVES) this.lives -= 1;
    redrawLives(this);

    if (this.lives > 0) {
        this.invulnerable = true;
        player.setTint(0xffd166);
        player.setVelocityY(-320);
        this.board.setAngle(-6);
        this.cameras.main.shake(140, 0.006);

        this.tweens.add({
            targets: [player, this.board],
            alpha: 0.25,
            duration: 90,
            yoyo: true,
            repeat: 5
        });

        this.time.delayedCall(1150, () => {
            if (!player.active) return;
            player.clearTint();
            player.setAlpha(1);
            this.board.setAlpha(1);
            this.invulnerable = false;
        });
        return;
    }

    this.gameOver = true;

    player.setTint(0xd35b52);
    player.setVelocity(120, -320);
    player.setAngularVelocity(260);
    this.board.setAngle(18);

    this.physics.world.pause();

    const overlay = this.add.graphics().setDepth(50);
    overlay.fillStyle(0x101820, 0.72);
    overlay.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

    this.add.text(GAME_WIDTH / 2, GAME_HEIGHT / 2 - 85, 'WIPEOUT!', {
        fontFamily: 'monospace',
        fontSize: '76px',
        fontStyle: 'bold',
        color: '#ffffff'
    }).setOrigin(0.5).setDepth(51);

    let gameOverMessage;
    if (this.score <= 2000) {
        gameOverMessage = 'Good try, but you still have a lot to learn';
    } else if (this.score <= 4000) {
        gameOverMessage = 'Not a bad start, keep it up';
    } else if (this.score <= 8000) {
        gameOverMessage = 'Great result, but you can do better';
    } else if (this.score <= 10000) {
        gameOverMessage = "Dude, you're awesome";
    } else {
        gameOverMessage = 'Skateboarding legend';
    }

    this.add.text(GAME_WIDTH / 2, GAME_HEIGHT / 2 + 5, gameOverMessage, {
        fontFamily: 'monospace',
        fontSize: '36px',
        fontStyle: 'bold',
        color: '#ffd166',
        align: 'center',
        wordWrap: { width: GAME_WIDTH - 120 }
    }).setOrigin(0.5).setDepth(51);

    this.add.text(GAME_WIDTH / 2, GAME_HEIGHT / 2 + 68, `Distance: ${this.score} m`, {
        fontFamily: 'monospace',
        fontSize: '34px',
        color: '#cceaf1'
    }).setOrigin(0.5).setDepth(51);

    this.add.text(GAME_WIDTH / 2, GAME_HEIGHT / 2 + 125, 'TAP or SPACE to restart', {
        fontFamily: 'monospace',
        fontSize: '30px',
        color: '#ffe39a'
    }).setOrigin(0.5).setDepth(51);
}
